dictionaries.ps=ps;dictionaries['fa-AF']=fa;
let language='en';
export function setLanguage(value){language=Object.hasOwn(dictionaries,value)?value:'en';document.documentElement.lang=language;document.documentElement.dir=language==='en'?'ltr':'rtl';}
export function t(key){return dictionaries[language][key]||dictionaries.en[key]||key.replaceAll('_',' ');}
export function translatePage(root=document){root.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));root.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));}
export function getLanguage(){return language;}
